const assert = require('node:assert/strict');
const { readFileSync } = require('node:fs');
const path = require('node:path');
const test = require('node:test');

test('rooms fixture contains valid rooms with unique ids', () => {
  const fixturePath = path.join(__dirname, '..', 'data', 'rooms.json');
  const rooms = JSON.parse(readFileSync(fixturePath, 'utf8'));

  assert.ok(Array.isArray(rooms), 'fixture root must be an array');
  assert.ok(rooms.length > 0, 'fixture must contain at least one room');

  const ids = new Set();

  for (const [index, room] of rooms.entries()) {
    assert.ok(room !== null && typeof room === 'object' && !Array.isArray(room), `room at index ${index} must be an object`);

    assert.equal(typeof room.id, 'string', `room at index ${index} must have a string id`);
    assert.ok(room.id.trim().length > 0, `room at index ${index} must have a non-empty id`);
    assert.ok(!ids.has(room.id), `room id must be unique: ${room.id}`);
    ids.add(room.id);

    assert.equal(typeof room.name, 'string', `room ${room.id} must have a string name`);
    assert.ok(room.name.trim().length > 0, `room ${room.id} must have a non-empty name`);
    assert.equal(typeof room.building, 'string', `room ${room.id} must have a string building`);
    assert.ok(room.building.trim().length > 0, `room ${room.id} must have a non-empty building`);
    assert.ok(Number.isInteger(room.capacity) && room.capacity > 0, `room ${room.id} must have a positive integer capacity`);
    assert.ok(Number.isInteger(room.floor), `room ${room.id} must have an integer floor`);
    assert.ok(Array.isArray(room.features), `room ${room.id} must have a features array`);
    assert.ok(room.features.every((feature) => typeof feature === 'string'), `room ${room.id} features must all be strings`);
  }
});

