const ALLOWED_PARAMETERS = new Set(["name", "minCapacity"]);

/**
 * Parse and validate room search criteria from URL query parameters.
 *
 * @param {URLSearchParams} searchParams
 * @returns {{ name: string | undefined, minCapacity: number | undefined }}
 */
export function parseRoomQuery(searchParams) {
  if (!(searchParams instanceof URLSearchParams)) {
    throw new TypeError("searchParams must be a URLSearchParams instance");
  }

  for (const [key] of searchParams) {
    if (!ALLOWED_PARAMETERS.has(key)) {
      throw new Error(`Unknown query parameter: ${key}`);
    }
  }

  for (const key of ALLOWED_PARAMETERS) {
    if (searchParams.getAll(key).length > 1) {
      throw new Error(`Query parameter '${key}' must not be repeated`);
    }
  }

  let name;
  if (searchParams.has("name")) {
    name = searchParams.get("name").trim();
    if (name.length === 0) {
      throw new Error("Query parameter 'name' must not be empty");
    }
  }

  let minCapacity;
  if (searchParams.has("minCapacity")) {
    const value = searchParams.get("minCapacity").trim();
    if (value.length === 0) {
      throw new Error("Query parameter 'minCapacity' must not be empty");
    }
    if (!/^\d+$/.test(value)) {
      throw new Error("Query parameter 'minCapacity' must be a positive integer");
    }

    minCapacity = Number(value);
    if (!Number.isSafeInteger(minCapacity) || minCapacity <= 0) {
      throw new Error("Query parameter 'minCapacity' must be a positive integer");
    }
  }

  return { name, minCapacity };
}

