const rooms = require('../data/rooms.json');

function searchRooms({ name, minCapacity } = {}) {
  const normalizedName = typeof name === 'string' ? name.toLocaleLowerCase() : '';

  return rooms.filter((room) => {
    const matchesName = normalizedName === '' || room.name.toLocaleLowerCase().includes(normalizedName);
    const matchesCapacity = minCapacity === undefined || room.capacity >= minCapacity;

    return matchesName && matchesCapacity;
  });
}

module.exports = searchRooms;

