import test from "node:test";
import assert from "node:assert/strict";

import { parseRoomQuery } from "../src/query.js";

test("returns undefined criteria when no parameters are provided", () => {
  assert.deepEqual(parseRoomQuery(new URLSearchParams()), {
    name: undefined,
    minCapacity: undefined,
  });
});

test("trims name and parses minCapacity as a number", () => {
  assert.deepEqual(
    parseRoomQuery(new URLSearchParams("name=%20Study%20Room%20&minCapacity=12")),
    { name: "Study Room", minCapacity: 12 },
  );
});

test("accepts either supported parameter on its own", () => {
  assert.deepEqual(parseRoomQuery(new URLSearchParams("name=Lab")), {
    name: "Lab",
    minCapacity: undefined,
  });
  assert.deepEqual(parseRoomQuery(new URLSearchParams("minCapacity=1")), {
    name: undefined,
    minCapacity: 1,
  });
});

test("rejects unknown parameters", () => {
  assert.throws(() => parseRoomQuery(new URLSearchParams("campus=north")), /Unknown query parameter: campus/);
});

test("rejects repeated parameters", () => {
  assert.throws(() => parseRoomQuery(new URLSearchParams("name=A&name=B")), /must not be repeated/);
  assert.throws(() => parseRoomQuery(new URLSearchParams("minCapacity=2&minCapacity=3")), /must not be repeated/);
});

test("rejects names that are empty after trimming", () => {
  assert.throws(() => parseRoomQuery(new URLSearchParams("name=%20%20")), /name.*must not be empty/);
});

test("rejects empty, non-integer, zero, negative, and unsafe minCapacity values", () => {
  for (const value of ["", " ", "1.5", "abc", "0", "-2", "9007199254740992"]) {
    assert.throws(
      () => parseRoomQuery(new URLSearchParams([ ["minCapacity", value] ])),
      /minCapacity.*(?:empty|positive integer)/,
      `expected ${JSON.stringify(value)} to be rejected`,
    );
  }
});

