const assert = require('node:assert/strict');
const { readFileSync } = require('node:fs');
const path = require('node:path');
const test = require('node:test');
const searchRooms = require('../src/rooms');

const fixtureRooms = JSON.parse(
  readFileSync(path.join(__dirname, '..', 'data', 'rooms.json'), 'utf8'),
);

test('returns all rooms when no criteria are provided', () => {
  assert.deepEqual(searchRooms(), fixtureRooms);
});

test('filters room names by substring', () => {
  assert.deepEqual(searchRooms({ name: 'аудитория' }), [fixtureRooms[1]]);
});

test('filters rooms by minimum capacity, including the boundary', () => {
  assert.deepEqual(searchRooms({ minCapacity: 24 }), [fixtureRooms[0], fixtureRooms[1]]);
});

test('matches room names without regard to case', () => {
  assert.deepEqual(searchRooms({ name: 'КОМНАТА' }), [fixtureRooms[2]]);
});

test('returns an empty list when no rooms match', () => {
  assert.deepEqual(searchRooms({ name: 'несуществующее помещение' }), []);
});

