import { createRequire } from "node:module";
import { pathToFileURL } from "node:url";
import { createServer as createHttpServer } from "node:http";

import { parseRoomQuery } from "./query.js";

const require = createRequire(import.meta.url);
const searchRooms = require("./rooms.js");

function sendJson(response, statusCode, body) {
  response.writeHead(statusCode, { "content-type": "application/json; charset=utf-8" });
  response.end(JSON.stringify(body));
}

export function createServer() {
  return createHttpServer((request, response) => {
    let pathname;
    try {
      pathname = new URL(request.url, "http://localhost").pathname;
    } catch {
      sendJson(response, 400, { error: "Invalid request URL" });
      return;
    }

    if (pathname !== "/api/rooms") {
      sendJson(response, 404, { error: "Not found" });
      return;
    }

    if (request.method !== "GET") {
      sendJson(response, 405, { error: "Method not allowed" });
      return;
    }

    try {
      const url = new URL(request.url, "http://localhost");
      const criteria = parseRoomQuery(url.searchParams);
      sendJson(response, 200, { rooms: searchRooms(criteria) });
    } catch (error) {
      sendJson(response, 400, { error: error.message });
    }
  });
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  const server = createServer();
  const port = Number(process.env.PORT || 3000);
  server.listen(port, "0.0.0.0", () => {
    console.log(`Room server listening on 0.0.0.0:${port}`);
  });
}

