import test from "node:test";
import assert from "node:assert/strict";

import { createServer } from "../src/server.js";

async function withServer(run) {
  const server = createServer();
  await new Promise((resolve, reject) => {
    server.once("error", reject);
    server.listen(0, "127.0.0.1", resolve);
  });

  const address = server.address();
  const baseUrl = `http://127.0.0.1:${address.port}`;
  try {
    await run(baseUrl);
  } finally {
    await new Promise((resolve, reject) => {
      server.close((error) => (error ? reject(error) : resolve()));
    });
  }
}

test("GET /api/rooms returns rooms as JSON", async () => {
  await withServer(async (baseUrl) => {
    const response = await fetch(`${baseUrl}/api/rooms`);
    const body = await response.json();

    assert.equal(response.status, 200);
    assert.ok(Array.isArray(body.rooms));
    assert.ok(body.rooms.length > 0);
  });
});

test("GET /api/rooms applies validated search parameters", async () => {
  await withServer(async (baseUrl) => {
    const response = await fetch(`${baseUrl}/api/rooms?minCapacity=24`);
    const body = await response.json();

    assert.equal(response.status, 200);
    assert.ok(body.rooms.length > 0);
    assert.ok(body.rooms.every((room) => room.capacity >= 24));
  });
});

test("invalid query parameters return HTTP 400 with a JSON error", async () => {
  await withServer(async (baseUrl) => {
    const response = await fetch(`${baseUrl}/api/rooms?unknown=value`);
    const body = await response.json();

    assert.equal(response.status, 400);
    assert.equal(typeof body.error, "string");
  });
});

test("unknown paths return HTTP 404", async () => {
  await withServer(async (baseUrl) => {
    const response = await fetch(`${baseUrl}/unknown`);
    assert.equal(response.status, 404);
  });
});

test("unsupported methods on /api/rooms return HTTP 405", async () => {
  await withServer(async (baseUrl) => {
    const response = await fetch(`${baseUrl}/api/rooms`, { method: "POST" });
    assert.equal(response.status, 405);
  });
});

