import assert from "node:assert/strict";
import { spawn } from "node:child_process";
import { createServer as createNetServer } from "node:net";
import { setTimeout as delay } from "node:timers/promises";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import test from "node:test";

const projectRoot = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const fixtureRoomName = "Тихий читальный зал";
const readinessTimeoutMs = 5_000;
const processExitTimeoutMs = 1_500;

async function getFreePort() {
  const server = createNetServer();
  server.listen(0, "127.0.0.1");
  await new Promise((resolveListen, reject) => {
    server.once("listening", resolveListen);
    server.once("error", reject);
  });

  const { port } = server.address();
  await new Promise((resolveClose, reject) => {
    server.close((error) => (error ? reject(error) : resolveClose()));
  });
  return port;
}

function waitForExit(child, timeoutMs) {
  if (child.exitCode !== null || child.signalCode !== null) {
    return Promise.resolve(true);
  }

  return new Promise((resolveExit) => {
    const timer = setTimeout(() => {
      child.off("exit", onExit);
      resolveExit(false);
    }, timeoutMs);

    function onExit() {
      clearTimeout(timer);
      resolveExit(true);
    }

    child.once("exit", onExit);
  });
}

async function stopChild(child) {
  if (child.exitCode !== null || child.signalCode !== null) return;

  child.kill();
  if (await waitForExit(child, processExitTimeoutMs)) return;

  child.kill("SIGKILL");
  const exited = await waitForExit(child, processExitTimeoutMs);
  assert.equal(exited, true, "server process did not exit after SIGKILL");
}

test(
  "rooms API works over HTTP in a child server process",
  { timeout: 15_000 },
  async (t) => {
    const port = await getFreePort();
    const child = spawn(process.execPath, ["src/server.js"], {
      cwd: projectRoot,
      env: { ...process.env, PORT: String(port) },
      stdio: ["ignore", "ignore", "pipe"],
    });
    let stderr = "";
    child.stderr.setEncoding("utf8");
    child.stderr.on("data", (chunk) => {
      stderr = (stderr + chunk).slice(-4_000);
    });
    child.on("error", () => {});
    t.after(() => stopChild(child));

    const baseUrl = `http://127.0.0.1:${port}/api/rooms`;
    const deadline = Date.now() + readinessTimeoutMs;
    let ready = false;
    let startupError;

    while (Date.now() < deadline) {
      if (child.exitCode !== null || child.signalCode !== null) {
        startupError = new Error(`server exited before becoming ready: ${stderr}`);
        break;
      }

      try {
        const response = await fetch(baseUrl, { signal: AbortSignal.timeout(500) });
        if (response.ok) {
          ready = true;
          break;
        }
      } catch {
        // The server may not have started listening yet; retry until the deadline.
      }
      await delay(50);
    }

    assert.equal(ready, true, startupError?.message ?? "server readiness timed out");

    const listResponse = await fetch(baseUrl);
    assert.equal(listResponse.status, 200);
    const listBody = await listResponse.json();
    assert.ok(Array.isArray(listBody.rooms));
    assert.ok(listBody.rooms.some((room) => room.name === fixtureRoomName));

    const filterResponse = await fetch(`${baseUrl}?name=${encodeURIComponent(fixtureRoomName)}`);
    assert.equal(filterResponse.status, 200);
    const filterBody = await filterResponse.json();
    assert.ok(Array.isArray(filterBody.rooms));
    assert.ok(filterBody.rooms.length > 0);
    assert.ok(filterBody.rooms.every((room) => room.name.includes(fixtureRoomName)));

    const missingResponse = await fetch(
      `${baseUrl}?name=${encodeURIComponent("__missing_room_name_7f3c9a__")}`,
    );
    assert.equal(missingResponse.status, 200);
    const missingBody = await missingResponse.json();
    assert.deepEqual(missingBody.rooms, []);

    const invalidResponse = await fetch(`${baseUrl}?minCapacity=invalid`);
    assert.equal(invalidResponse.status, 400);
    const invalidBody = await invalidResponse.json();
    assert.equal(typeof invalidBody.error, "string");
  },
);

