const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const test = require('node:test');

const roomsFile = path.resolve(process.cwd(), 'data/rooms.json');

function readRooms() {
  const contents = fs.readFileSync(roomsFile, 'utf8');
  return JSON.parse(contents);
}

test('data/rooms.json is valid JSON containing multiple rooms with the contracted schema', () => {
  const rooms = readRooms();

  assert.ok(Array.isArray(rooms), 'root value must be an array');
  assert.ok(rooms.length > 1, 'expected multiple room entries');

  const ids = new Set();
  for (const [index, room] of rooms.entries()) {
    assert.ok(room !== null && typeof room === 'object' && !Array.isArray(room), `room at index ${index} must be an object`);
    assert.equal(typeof room.id, 'string', `room at index ${index} must have a string id`);
    assert.ok(!ids.has(room.id), `room id must be unique: ${room.id}`);
    ids.add(room.id);

    for (const field of ['name', 'building']) {
      assert.equal(typeof room[field], 'string', `room at index ${index} must have a string ${field}`);
      assert.ok(room[field].trim().length > 0, `room at index ${index} must have a non-empty ${field}`);
    }

    assert.ok(Number.isInteger(room.capacity) && room.capacity > 0, `room at index ${index} must have a positive integer capacity`);
    assert.ok(Number.isInteger(room.floor), `room at index ${index} must have an integer floor`);
    assert.ok(Array.isArray(room.features), `room at index ${index} must have a features array`);
    for (const [featureIndex, feature] of room.features.entries()) {
      assert.equal(typeof feature, 'string', `feature at room ${index}, index ${featureIndex} must be a string`);
    }
  }
});

