import test from 'node:test';
import assert from 'node:assert/strict';
import { pathToFileURL } from 'node:url';
import { resolve } from 'node:path';

// CONTRACTS.md names src/query.js as the module under test. Resolve that exact
// contract path from the project root where the controller runs this suite.
const moduleUrl = pathToFileURL(resolve(process.cwd(), 'src/query.js'));
const { parseRoomQuery } = await import(moduleUrl.href);

function parse(search) {
  return parseRoomQuery(new URLSearchParams(search));
}

function assertMeaningfulError(search) {
  assert.throws(
    () => parse(search),
    (error) => {
      assert.ok(error instanceof Error, 'invalid input must throw an Error');
      assert.equal(typeof error.message, 'string');
      assert.ok(error.message.trim().length > 0, 'error message must be meaningful');
      return true;
    },
  );
}

test('accepts an absent parameter set and returns normalized criteria', () => {
  const result = parse('');
  assert.ok(result !== null && typeof result === 'object' && !Array.isArray(result));
});

test('accepts supported name and positive integer minCapacity values', () => {
  const result = parse('name=Meeting%20Room&minCapacity=4');
  assert.ok(result !== null && typeof result === 'object' && !Array.isArray(result));
});

test('normalizes surrounding whitespace in name consistently', () => {
  assert.deepEqual(parse('name=Meeting%20Room'), parse('name=%20Meeting%20Room%20'));
});

test('rejects an unknown parameter with a meaningful error', () => {
  assertMeaningfulError('building=north');
});

test('rejects repeated parameters with a meaningful error', () => {
  assertMeaningfulError('name=One&name=Two');
});

test('rejects an empty name with a meaningful error', () => {
  assertMeaningfulError('name=');
});

test('rejects an empty minCapacity with a meaningful error', () => {
  assertMeaningfulError('minCapacity=');
});

test('rejects minCapacity values that are not positive integers', () => {
  for (const value of ['0', '-2', '1.5', 'many']) {
    assertMeaningfulError(`minCapacity=${encodeURIComponent(value)}`);
  }
});

