import test from "node:test";
import assert from "node:assert/strict";
import { readFile } from "node:fs/promises";
import path from "node:path";
import { pathToFileURL } from "node:url";

const root = process.cwd();
const fixturePath = path.join(root, "data", "rooms.json");
const modulePath = path.join(root, "src", "rooms.js");
const rooms = JSON.parse(await readFile(fixturePath, "utf8"));
async function loadSearchRooms() {
  const exportsFromModule = await import(pathToFileURL(modulePath).href);
  const exportedFunctions = Object.entries(exportsFromModule).filter(([, value]) => typeof value === "function");
  const searchRooms = typeof exportsFromModule.default === "function"
    ? exportsFromModule.default
    : exportedFunctions.length === 1
      ? exportedFunctions[0][1]
      : undefined;
  assert.equal(typeof searchRooms, "function", "src/rooms.js must export one searchable function");
  return searchRooms;
}

function sortedByName(records) {
  assert.ok(Array.isArray(records), "search result must be an array of room records");
  return [...records].sort((a, b) => a.name.localeCompare(b.name, "ru"));
}

test("name filter matches a case-insensitive substring from the existing fixture", async () => {
  const searchRooms = await loadSearchRooms();
  assert.ok(rooms.length > 0, "the available data/rooms.json fixture must contain a room");
  const sampleName = rooms[0].name;
  const substring = sampleName.slice(1, -1);
  assert.ok(substring.length > 0, "fixture room name must provide a substring");
  const query = substring.toLocaleUpperCase("ru");
  const expected = rooms.filter(room => room.name.toLocaleLowerCase("ru").includes(query.toLocaleLowerCase("ru")));
  assert.deepEqual(sortedByName(searchRooms({ name: query })), sortedByName(expected));
});

test("minCapacity includes rooms whose capacity is at least the requested minimum", async () => {
  const searchRooms = await loadSearchRooms();
  const threshold = rooms[0].capacity;
  const expected = rooms.filter(room => room.capacity >= threshold);
  assert.deepEqual(sortedByName(searchRooms({ minCapacity: threshold })), sortedByName(expected));
  assert.ok(expected.some(room => room.capacity === threshold), "fixture must cover the inclusive boundary");
});

test("no filters return every record from the existing fixture", async () => {
  const searchRooms = await loadSearchRooms();
  assert.deepEqual(sortedByName(searchRooms({})), sortedByName(rooms));
});

test("a name with no fixture match returns an empty array", async () => {
  const searchRooms = await loadSearchRooms();
  const query = "__makora_no_room_match__";
  assert.equal(rooms.some(room => room.name.toLocaleLowerCase("ru").includes(query)), false);
  assert.deepEqual(searchRooms({ name: query }), []);
});

