import assert from 'node:assert/strict';
import { after, before, describe, test } from 'node:test';
import { readFile } from 'node:fs/promises';
import { resolve } from 'node:path';
import { pathToFileURL } from 'node:url';

const projectRoot = process.cwd();
let server;
let baseUrl;
let mockRooms;

async function request(path, options) {
  return fetch(`${baseUrl}${path}`, options);
}

async function readJson(response) {
  return response.json();
}

test('the declared rooms mock is a non-empty JSON array with room names', async () => {
  const rooms = JSON.parse(await readFile(resolve(projectRoot, 'data/rooms.json'), 'utf8'));
  assert.ok(Array.isArray(rooms));
  assert.ok(rooms.length > 0);
  assert.ok(rooms.every(room => typeof room.name === 'string'));
});

describe('HTTP API contract', () => {
before(async () => {
  mockRooms = JSON.parse(await readFile(resolve(projectRoot, 'data/rooms.json'), 'utf8'));
  const moduleUrl = pathToFileURL(resolve(projectRoot, 'src/server.js')).href;
  const serverModule = await import(moduleUrl);
  const createServer = serverModule.createServer ?? serverModule.default?.createServer;
  assert.equal(typeof createServer, 'function', 'src/server.js must export createServer()');

  server = createServer();
  assert.equal(typeof server?.listen, 'function', 'createServer() must return a listenable HTTP server');
  await new Promise((resolveListen, rejectListen) => {
    server.once('error', rejectListen);
    server.listen(0, '127.0.0.1', resolveListen);
  });
  const address = server.address();
  baseUrl = `http://127.0.0.1:${address.port}`;
});

after(async () => {
  if (server?.listening) {
    await new Promise((resolveClose, rejectClose) => {
      server.close(error => error ? rejectClose(error) : resolveClose());
    });
  }
});

test('GET /api/rooms returns HTTP 200 and the rooms JSON list', async () => {
  const response = await request('/api/rooms');
  assert.equal(response.status, 200);
  assert.deepEqual(await readJson(response), { rooms: mockRooms });
});

test('GET /api/rooms?name= filters the JSON list by a mock room name', async () => {
  const expectedName = mockRooms[0]?.name;
  assert.equal(typeof expectedName, 'string', 'the declared rooms mock must include a name');
  const response = await request(`/api/rooms?name=${encodeURIComponent(expectedName)}`);
  assert.equal(response.status, 200);
  const body = await readJson(response);
  assert.ok(Array.isArray(body.rooms), 'response JSON must contain a rooms array');
  assert.deepEqual(body.rooms, mockRooms.filter(room => room.name === expectedName));
});

test('a name filter with no matches returns an empty rooms array', async () => {
  const response = await request('/api/rooms?name=__no_such_room_name__');
  assert.equal(response.status, 200);
  assert.deepEqual(await readJson(response), { rooms: [] });
});

test('an unsupported query parameter returns HTTP 400 and a JSON error', async () => {
  const response = await request('/api/rooms?unsupported_parameter=x');
  assert.equal(response.status, 400);
  const body = await readJson(response);
  assert.ok(body && typeof body === 'object' && !Array.isArray(body));
  assert.ok(Object.hasOwn(body, 'error'), 'validation error JSON must contain error');
});

test('an unknown route returns HTTP 404', async () => {
  const response = await request('/api/unknown');
  assert.equal(response.status, 404);
});

test('an unsupported method on /api/rooms returns HTTP 405', async () => {
  const response = await request('/api/rooms', { method: 'POST' });
  assert.equal(response.status, 405);
});
});

