  assert.equal(response.status, 200);
  assert.ok(body && Array.isArray(body.rooms), 'response must contain rooms as an array');
  assert.ok(body.rooms.every(room => room && typeof room.name === 'string'),
    'each room must expose its name in the name field');
});

test('GET /api/rooms?name= filters the list by the room name field', async () => {
  const query = '?name=' + encodeURIComponent(MATCHING_ROOM_NAME);
  const { response, body } = await getRooms(query);
  assert.equal(response.status, 200);
  assert.ok(body && Array.isArray(body.rooms), 'response must contain rooms as an array');
  assert.ok(body.rooms.length > 0, 'the known room name from data/rooms.json must match');
  assert.ok(body.rooms.every(room => room && room.name === MATCHING_ROOM_NAME),
    'every returned room must match the requested name');
});

test('GET /api/rooms with a name absent from the supplied mock returns an empty array', async () => {
  const { response, body } = await getRooms('?name=__makora_no_such_room__');
  assert.equal(response.status, 200);
  assert.ok(body && Array.isArray(body.rooms), 'response must contain rooms as an array');
  assert.deepEqual(body.rooms, []);
});

test('GET /api/rooms?minCapacity=invalid returns HTTP 400', async () => {
  const response = await fetch(baseUrl + '/api/rooms?minCapacity=invalid', {
    signal: AbortSignal.timeout(REQUEST_TIMEOUT_MS),
  });
  assert.equal(response.status, 400);
});

'use strict';

const assert = require('node:assert/strict');
const { spawn } = require('node:child_process');
const net = require('node:net');
const { after, before, test } = require('node:test');

const STARTUP_TIMEOUT_MS = 5000;
const SHUTDOWN_TIMEOUT_MS = 2500;
const REQUEST_TIMEOUT_MS = 3000;
const MATCHING_ROOM_NAME = 'Тихий читальный зал';

let child;
let port;
let closePromise;
let spawnError;
let baseUrl;

function delay(ms) {
  return new Promise(resolve => setTimeout(resolve, ms));
}

function waitForClose(timeoutMs) {
  return Promise.race([
    closePromise.then(() => true),
    delay(timeoutMs).then(() => false),
  ]);
}

async function reserveEphemeralPort() {
  const listener = net.createServer();
  await new Promise((resolve, reject) => {
    listener.once('error', reject);
    listener.listen(0, '127.0.0.1', resolve);
  });
  const address = listener.address();
  assert.ok(address && typeof address === 'object');
  const selectedPort = address.port;
  await new Promise((resolve, reject) => listener.close(error => error ? reject(error) : resolve()));
  return selectedPort;
}

async function waitForServer() {
  const deadline = Date.now() + STARTUP_TIMEOUT_MS;
  let lastError;
  while (Date.now() < deadline) {
    if (spawnError) throw spawnError;
    if (child.exitCode !== null || child.signalCode !== null) {
      throw new Error('server process exited before becoming ready');
    }
    try {
      const response = await fetch(baseUrl + '/api/rooms', {
        signal: AbortSignal.timeout(REQUEST_TIMEOUT_MS),
      });
      if (response.status === 200) return;
      lastError = new Error('readiness request returned HTTP ' + response.status);
    } catch (error) {
      lastError = error;
    }
    await delay(50);
  }
  throw new Error('server did not become ready within ' + STARTUP_TIMEOUT_MS + 'ms: ' + (lastError?.message ?? 'no response'));
}

async function getRooms(query = '') {
  const response = await fetch(baseUrl + '/api/rooms' + query, {
    signal: AbortSignal.timeout(REQUEST_TIMEOUT_MS),
  });
  let body;
  try {
    body = await response.json();
  } catch (error) {
    throw new Error('expected JSON response for HTTP ' + response.status + ': ' + error.message);
  }
  return { response, body };
}

before(async () => {
  port = await reserveEphemeralPort();
  baseUrl = 'http://127.0.0.1:' + port;
  child = spawn(process.execPath, ['src/server.js'], {
    cwd: process.cwd(),
    env: { ...process.env, PORT: String(port) },
    stdio: 'ignore',
    windowsHide: true,
  });
  child.once('error', error => { spawnError = error; });
  closePromise = new Promise(resolve => {
    child.once('close', (code, signal) => resolve({ code, signal }));
  });
  await waitForServer();
}, { timeout: STARTUP_TIMEOUT_MS + 2000 });

after(async () => {
  if (!child || child.pid === undefined) return;

  if (child.exitCode === null && child.signalCode === null) {
    try { child.kill('SIGTERM'); } catch {}
  }
  let closed = await waitForClose(SHUTDOWN_TIMEOUT_MS);
  if (!closed) {
    try { child.kill('SIGKILL'); } catch {}
    closed = await waitForClose(SHUTDOWN_TIMEOUT_MS);
  }
  assert.ok(closed, 'the child server process must stop within the bounded shutdown timeout');
  assert.ok(child.exitCode !== null || child.signalCode !== null,
    'the child server process must be stopped when the test suite finishes');
}, { timeout: SHUTDOWN_TIMEOUT_MS * 2 + 1000 });

test('starts the API server as a child process on the assigned PORT', () => {
  assert.ok(child && child.pid !== undefined, 'server must be started as a child process');
  assert.ok(port > 0 && port <= 65535, 'the child must receive an assigned TCP port');
  assert.equal(child.exitCode, null, 'server process should be alive while requests are tested');
  assert.equal(child.signalCode, null, 'server process should not have been terminated before requests');
});

